@IsTest private class OwnedClockReadTest {
 @IsTest static void compareClock() {
  Time earlier=Time.newInstance(8,9,10,11); Time later=earlier.addMilliseconds(1);
  Account row=new Account(Name='owned clock',OwnedClock__c=earlier);Database.insert(row,AccessLevel.SYSTEM_MODE);
  row=[SELECT OwnedClock__c,OwnedClockFormula__c FROM Account WHERE Id=:row.Id WITH SYSTEM_MODE];
  System.assert(row.OwnedClock__c < later);System.assert(row.OwnedClock__c <= earlier);
  System.assert(later > row.OwnedClock__c);System.assert(earlier >= row.OwnedClock__c);
  System.assertEquals(earlier,row.OwnedClock__c);System.assertEquals(11,row.OwnedClock__c.millisecond());
  Account decoded=(Account)JSON.deserialize(JSON.serialize(row),Account.class);
  System.assertEquals(earlier,decoded.OwnedClock__c);System.assert(decoded.OwnedClock__c <= earlier);
  System.assertEquals('08:09:10.011Z',String.valueOf(decoded.OwnedClock__c));
  System.assert(row.OwnedClockFormula__c < later);System.assert(row.OwnedClockFormula__c <= earlier);
  System.assert(later > row.OwnedClockFormula__c);System.assert(earlier >= row.OwnedClockFormula__c);
  System.assertEquals(earlier,row.OwnedClockFormula__c);System.assertEquals(11,row.OwnedClockFormula__c.millisecond());
  System.assertEquals(earlier,(Time)row.get('OwnedClockFormula__c'));
  Time empty=null;System.assertEquals(false,row.OwnedClock__c < empty);System.assertEquals(false,row.OwnedClockFormula__c < empty);
 }
}

